import { useState, useCallback } from 'react';

import Card from '@mui/material/Card';
import Stack from '@mui/material/Stack';
import Button from '@mui/material/Button';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import CardHeader from '@mui/material/CardHeader';

import { useBoolean } from 'src/hooks/use-boolean';

import { useTranslate } from 'src/locales';
import { useDispatch } from 'src/redux/store';
import { getWallet, postDeposit, postManualDeposit, postWithdrawal } from 'src/redux/slices/wallet';
import { useSnackbar } from 'src/components/snackbar';

import Iconify from 'src/components/iconify';

import { fCurrency } from 'src/utils/format-number';
import { Deposit, Withdraw, WebPayment } from '../wallet';
// ----------------------------------------------------------------------

type Props = {
  wallet: any;
};

export default function AccountTransactionWallet({ wallet }: Props) {
  const dispatch = useDispatch();
  const { t } = useTranslate();
  const { enqueueSnackbar } = useSnackbar();
  const depositForm = useBoolean();
  const withdrawForm = useBoolean();
  const webPayment = useBoolean();
  const [paymentUrl, setPaymentUrl] = useState('');
  const handleDeposit = useCallback(async (deposit: any) => {
    try {
      if (deposit.paymentMethod === 'MANUAL') {
        const fd = new FormData();
        fd.append('method', 'MANUAL');
        fd.append('amount', String(deposit.amount));
        if (deposit.receipt) fd.append('receipt', deposit.receipt);

        await postManualDeposit(fd);
        enqueueSnackbar(t('wallet.submitted_for_review') || 'Submitted for review', {
          variant: 'success',
        });
        setPaymentUrl('');
        return;
      }

      const result = await postDeposit({ method: deposit.paymentMethod, amount: deposit.amount });
      if (result.redirect_url) {
        setPaymentUrl(result.redirect_url);
        webPayment.onTrue();
      } else {
        alert('Failed to initiate payment');
        setPaymentUrl('');
      }
    } catch (error) {
      console.error('Error initiating payment:', error?.response?.data);
      const errorMessage =
        typeof error?.response?.data === 'string'
          ? error?.response?.data
          : error?.response?.data?.non_field_errors[0];
      enqueueSnackbar(errorMessage, {
        variant: 'error',
      });
      setPaymentUrl('');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleWithdraw = useCallback(async (retr: any) => {
    try {
      await postWithdrawal({
        retraitMethod: retr.retraitMethod,
        amount: retr.amount,
        phoneNumber: retr.phoneNumber,
        rut: retr.rut,
        accountType: retr.accountType,
      });
      await dispatch(getWallet());
      enqueueSnackbar(t('wallet.withdraw_success'));
    } catch (error) {
      console.error('Error initiating withdraw:', error);
      const errorMessage =
        typeof error?.response?.data === 'string'
          ? error?.response?.data
          : error?.response?.data?.non_field_errors?.[0] || 'Error';
      enqueueSnackbar(errorMessage, { variant: 'error' });
      setPaymentUrl('');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Card>
      <CardHeader title={t('wallet.wallet')} />

      <Stack spacing={3} sx={{ px: 3, py: 1 }}>
        <Typography variant="h4">
          {fCurrency(wallet?.balance, false)} {wallet?.currency}
        </Typography>
      </Stack>
      <Divider sx={{ borderStyle: 'dashed' }} />

      <Stack spacing={1.5} direction="row" justifyContent="flex-end" sx={{ p: 3 }}>
        <Button
          onClick={depositForm.onTrue}
          variant="contained"
          color="primary"
          startIcon={<Iconify width={20} icon="majesticons:money-plus-line" />}
        >
          {t('wallet.deposit')}
        </Button>
        <Button
          onClick={withdrawForm.onTrue}
          variant="outlined"
          color="secondary"
          startIcon={<Iconify width={20} icon="majesticons:money-minus-line" />}
        >
          {t('wallet.withdraw')}
        </Button>
      </Stack>
      <Deposit open={depositForm.value} onClose={depositForm.onFalse} onCreate={handleDeposit} />
      <Withdraw
        open={withdrawForm.value}
        onClose={withdrawForm.onFalse}
        onCreate={handleWithdraw}
      />
      <WebPayment paymentUrl={paymentUrl} open={webPayment.value} onClose={webPayment.onFalse} />
    </Card>
  );
}
